<?php declare(strict_types=1);$event=$attendance['event'];$items=$attendance['items']; ?>
<section class="section"><div class="container-wide"><a href="/admin/events">← Events</a><div class="section-heading"><p class="eyebrow"><?= $e($event['event_date']) ?></p><h1><?= $e($event['title']) ?> attendees</h1></div><?php if($message):?><div class="notice" role="status"><?= $e($message) ?></div><?php endif;?><?php if($error):?><div class="form-error" role="alert"><?= $e($error) ?></div><?php endif;?><?php if($items===[]):?><div class="empty-state" role="status"><p>No registrations.</p></div><?php endif;?><?php foreach($items as$item):?><article class="admin-panel"><div class="programme-card-top"><strong><?= $e($item['registrant_name']) ?></strong><span class="status-pill"><?= $e(ucfirst($item['status'])) ?></span></div><p><?= $e($item['registrant_email']) ?> · <?= $e($item['registration_reference']) ?></p><?php if($item['status']==='registered'):?><form method="post" action="/admin/events/<?= rawurlencode($event['public_id']) ?>/attendees/<?= rawurlencode($item['public_id']) ?>/attend"><?= $csrf->field() ?><button class="btn btn-navy">Record attendance</button></form><form method="post" action="/admin/events/<?= rawurlencode($event['public_id']) ?>/attendees/<?= rawurlencode($item['public_id']) ?>/cancel"><?= $csrf->field() ?><button class="btn btn-outline">Cancel registration</button></form><?php endif;?></article><?php endforeach;?></div></section>
